/* IRON DIALECTIC — the programme trees of the Old Lands (The Three Continents). Each of the seven states has a
   national tree of about thirty programmes in three eras (the empire and the mandates; the interwar state; the
   cold war), with exclusive roads that lead to different countries, steps that act on neighbours, the oil and
   the overlord, three destinies, and national projects and foreign programmes (historical campaigns only).
   Row format: [suffix, name, x, y, {req, excl, reqAny, year, after, hist, ideos, fams, days}, desc, fx];
   ids are prefixed with the state's two letters. Loads after data/oldlands.js. */
(function () {
  'use strict';
  const ID = (globalThis.ID = globalThis.ID || {});
  const PERM = 600, B = ID.B;
  const RED = '#b5221a', INK = '#17140f', PAPER = '#ebe2cc', GOLD = '#d4a12a', GREEN = '#3f6b3a', NAVY = '#1f2a44', SKY = '#4f86b8', TEAL = '#1d7b80', BLUE = '#2b4a8c';
  const ids = (pre, a) => (a ? a.map((s) => pre + '_' + s) : a);
  const mk = (pre, r) => {
    const o = Object.assign({}, r[4] || {});
    for (const k of ['req', 'excl', 'reqAny']) if (o[k]) o[k] = ids(pre, o[k]);
    const f = Object.assign({ id: pre + '_' + r[0], name: r[1], x: r[2], y: r[3], days: 120, desc: r[5], fx: r[6] }, o);
    if (f.dest) { f.days = f.days === 120 ? 150 : f.days; f.fx.push(['threat', 8]); }
    return f;
  };
  /* a national tree; destinies rule each other out */
  const tree = (base, pre, rows, proj) => {
    const L = rows.map((r) => mk(pre, r));
    const ds = L.filter((f) => f.dest).map((f) => f.id);
    for (const f of L) if (f.dest) f.excl = (f.excl || []).concat(ds.filter((x) => x !== f.id));
    ID.FOCUS.nations[base] = L;
    const X = Math.max(...L.map((f) => f.x)) + 1.2;
    (ID.FOCUS.projects = ID.FOCUS.projects || {})[base] = proj.map((r) => Object.assign(mk(pre, [r[0], r[1], X + r[2], r[3], r[4], r[5], r[6]]), { proj: 1, foreign: r[7] ? 1 : undefined }));
  };
  const D = (name, motto, epithet, leader, quote, by, text, flag, art) => ({ name, motto, epithet, leader, quote, by, text, flag, art });
  const n2 = (b, k) => ['note2', b, k];

  /* ================================================================ Varanth: the sick man, the Gazi, the bridge */
  tree('Varanth', 'va', [
    ['tanzimat', 'The new regulations', 0, 0, { hist: 1, days: 100 }, 'Ministries on the western model, a civil code and a census: the empire reformed from the top, again.', [['mod', 'eff', 0.03, PERM, 'The new regulations'], ['nq', -4]]],
    ['railway', 'The pilgrim railway', 0, 1, { req: ['tanzimat'], hist: 1 }, 'A line from the capital to the holy cities of the south, paid for by the alms of the faithful and guarded by the army.', [['mod', 'trade', 0.04, PERM, 'The pilgrim railway'], ['sup', 'clergy', 6], ['op', 'Sahrem', 10], ['op', 'Amaran', 6]]],
    ['payoff', 'Pay off the Commission', 1, 1, { req: ['tanzimat'], excl: ['bonds'] }, 'Every coupon redeemed, the Debt Commission dissolved, the customs back in our hands. It will cost every piaster we have.', [['gold', -220], ['mod', 'rev', 0.07, PERM, 'The customs recovered'], ['legitmod', 4, 120, 'Free of the creditors']]],
    ['bonds', 'Hesperian loans', 2, 1, { req: ['tanzimat'], excl: ['payoff'] }, 'Hesperian banks will lend what the old creditors will not, and build the railway to the two rivers into the bargain.', [['gold', 200], ['op', 'Hesperia', 20], ['op', 'Norvik', -10], ['mod', 'rev', -0.04, 120, 'Hesperian interest']]],
    ['committee', 'The Committee of Union', 0, 2, { req: ['railway'], hist: 1 }, 'Young officers in a secret committee who mean to save the empire by making it a nation.', [['figLoy', 'army', 8], ['drift', 'thirdpos', 10], ['nq', 8], ['sup', 'military', 6]]],
    ['guard', 'The Sultan’s household guard', 1, 2, { req: ['railway'], excl: ['committee'], ideos: ['absmon', 'theocracy'] }, 'A guard of loyal mountain regiments, paid from the privy purse, to keep the palace safe from its own officers.', [['mod', 'coup', -0.4, PERM, 'The household guard'], ['tradition', 8], ['sup', 'military', -6]]],
    ['vilayets', 'Governors who listen', 2, 2, { reqAny: ['payoff', 'bonds'] }, 'Elected councils beside every governor of the vilayets, so that the provinces have a reason to stay.', [['fn', (G, n) => { for (const o of ID.Sov.dependents(G, n)) o.dep.res = Math.max(0, o.dep.res - 12); }], ['note', 'Resistance in every vilayet falls'], ['nq', -6]]],
    ['capital', 'A capital in the interior', 3, 0, { year: 1923, hist: 1, ideos: ['thirdpos', 'junta', 'natpop'] }, 'Move the government from the city of the sultans to a dusty town in the steppe, where the new state can build itself without the old one watching.', [['mod', 'eff', 0.04, PERM, 'The new capital'], ['mod', 'def', 0.05, PERM, 'The new capital'], ['tradition', -6]]],
    ['alphabet', 'The new alphabet', 3, 1, { req: ['capital'], hist: 1 }, 'The script of the Book replaced by the alphabet of the west, in three months, with the President at a blackboard in the town squares.', [['mod', 'sci', 0.08, PERM, 'The new alphabet'], ['tradition', -10], ['sup', 'clergy', -8], ['sup', 'intelligentsia', 6]]],
    ['statism', 'Statism', 4, 1, { req: ['capital'], excl: ['freeparty'], hist: 1 }, 'Sugar, textiles, steel and the railways built and owned by the state under a five-year plan with Karsovan advisers and no Karsovan ideas.', [['mod', 'prod', 0.06, PERM, 'Statism'], ['build', B.FACTORY, 2], ['sup', 'capital', -6], ['op', 'Karsova', 10]]],
    ['freeparty', 'The loyal opposition', 5, 1, { req: ['capital'], excl: ['statism'] }, 'The President allows an opposition party, to show the world the republic is free. It wins too many seats and is closed within the year, unless we let it live.', [['particip', 10], ['mandate', 8], ['mod', 'conf', 6, PERM, 'An opposition'], ['drift', 'liberal', 10]]],
    ['straits', 'The straits convention', 3, 2, { req: ['alphabet'], year: 1936, hist: 1 }, 'A conference at the lake gives the straits back to Varanth, with the right to fortify them.', [['mod', 'def', 0.06, PERM, 'The straits fortified'], ['mod', 'trade', 0.04, PERM, 'The straits'], n2('Lys', 'treaty')]],
    ['province', 'The province by the sea', 4, 2, { req: ['statism'], year: 1937 }, 'A coastal district of Tyrrha with a Varanthine minority: a plebiscite, a few thousand voters brought by train, and a new province.', [['claim', 'Tyrrha'], ['op', 'Tyrrha', -15], ['glory', 4]]],
    ['neutral', 'Neutral in the second war', 3, 3, { req: ['straits'], year: 1939, excl: ['chrome'], hist: 1 }, 'Sell to both sides, join neither, and enter the war in its last month on the side that has already won.', [['mod', 'def', 0.05, 120, 'Armed neutrality'], ['opAll', 4], ['gold', 80]]],
    ['chrome', 'Chrome for Hesperia', 4, 3, { req: ['straits'], year: 1939, excl: ['neutral'] }, 'Hesperia needs chrome for its armour and will pay in gold and guns.', [['gold', 160], ['op', 'Hesperia', 20], ['op', 'Norvik', -20], ['op', 'Cassine', -15]]],
    ['flank', 'The southern flank', 6, 0, { year: 1947, excl: ['third'], hist: 1 }, 'Karsova demands the straits and the eastern provinces. Cassine offers a guarantee, aid and a place in its alliance.', [['ally', 'Cassine'], ['op', 'Karsova', -25], ['mod', 'def', 0.06, PERM, 'The southern flank'], ['gold', 100]]],
    ['third', 'The third way abroad', 7, 0, { year: 1947, excl: ['flank'] }, 'Neither bloc: a seat among the non-aligned, and arms from whoever sells cheapest.', [['opAll', 4], ['sig', 10], ['mod', 'trade', 0.04, PERM, 'Open to all']]],
    ['elections', 'The first free elections', 6, 1, { req: ['flank'], year: 1950, hist: 1 }, 'The republic’s party loses the first free election in its history, and hands over power. The army watches.', [['ideology', 'liberal', 'election'], ['particip', 10], ['figLoy', 'army', -10]]],
    ['memorandum', 'The generals’ memorandum', 6, 2, { req: ['elections'], year: 1960, hist: 1 }, 'The army declares itself the guardian of the republic and its founder’s principles, and reserves the right to step in whenever it decides they are in danger.', [['mod', 'coup', -0.25, PERM, 'The army’s guardianship'], ['figLoy', 'army', 12], ['mandate', -8], ['drift', 'junta', 8]]],
    ['pacify', 'Pacify the mountains', 7, 1, { year: 1950, excl: ['valleys'], hist: 1 }, 'Gendarme posts on every ridge, the mountain language banned in schools, and the Dersan Front hunted village by village.', [['front', 'dersa', -20], ['grievance', 10], ['mod', 'unrest', -4, 120, 'The mountain posts'], ['nq', 8]]],
    ['valleys', 'Autonomy for the valleys', 8, 1, { year: 1950, excl: ['pacify'] }, 'Schools in the mountain language, an elected council in the valleys and an amnesty for the men in the hills.', [['front', 'dersa', -12], ['nq', -12], ['opAll', 4], ['sup', 'military', -6]]],
    ['drill', 'Drill the interior', 7, 2, { year: 1955 }, 'A state oil company with foreign drills and no foreign owners.', [['oil', 'find'], ['techUp', 'ind'], ['gold', -60]]],
    ['bridge', 'The bridge across the straits', 7, 3, { req: ['drill'], year: 1965 }, 'A suspension bridge between the two continents that meet at the capital.', [['mod', 'trade', 0.06, PERM, 'The bridge'], ['glory', 8], ['gold', -120]]],
    ['d_empire', 'The Sublime State', 0, 4, { req: ['guard'], ideos: ['absmon', 'theocracy'], dest: D('Sublime State of Varanth', 'The state is eternal.', 'The Empire Restored', 'Sultan Abdülmecid III', 'The empire did not die. It was only waiting for a sultan who understood it.', 'the Sultan, at his girding with the sword', 'The empire of many peoples survives the century that destroyed every other empire. Its provinces govern themselves, its peoples keep their languages, and its sultan reigns from the straits as his ancestors did.', { p: 'hband', a: RED, b: GOLD, e: 'crescent', ef: GOLD }, 'crown') },
      'Gird the Sultan with the sword of the founder in the old shrine by the straits, and proclaim that the empire of many peoples will outlive the century of nations.', [['legitmod', 10, 120, 'The Sublime State'], ['tradition', 15], ['nq', -20], ['fn', (G, n) => { for (const o of ID.Sov.dependents(G, n)) o.dep.res = Math.max(0, o.dep.res - 20); }]]],
    ['d_arrows', 'The Republic of the Six Arrows', 4, 4, { req: ['alphabet', 'statism'], ideos: ['thirdpos', 'junta', 'natpop'], dest: D('Republic of the Six Arrows', 'Peace at home, peace in the world.', 'Father of the Nation', 'The Gazi', 'We did not save the empire. We buried it, and built a country on the grave.', 'the Gazi, to the assembly', 'Republican, national, populist, statist, secular and revolutionary: six arrows on a red flag, and a country remade in fifteen years. The old empire is a museum.', { p: 'bicol', a: RED, b: PAPER, e: 'cogwheat', ef: PAPER }, 'industry') },
      'The six principles written into the constitution, the Gazi’s portrait in every classroom, and the army sworn to defend the republic against everyone, including itself.', [['legitmod', 10, 120, 'The Six Arrows'], ['mod', 'eff', 0.05, PERM, 'The Six Arrows'], ['nq', 15], ['sig', 15]]],
    ['d_bridge', 'The Bridge of Two Continents', 7, 4, { req: ['elections', 'bridge'], ideos: ['liberal', 'conmon', 'socdem', 'demsoc'], dest: D('Varanthine Commonwealth', 'Two continents, one people.', 'The Bridge', 'Prime Minister Selim Aydın', 'We were the sick man. Now we are the bridge, and everyone must cross us.', 'the Prime Minister, opening the bridge', 'A democracy at the meeting of two continents: free elections, a free market and the straits open to every flag. The western bloc calls it a model; the Old Lands call it a neighbour.', { p: 'cross', a: RED, b: PAPER, e: 'ring', ef: GOLD }, 'parliament') },
      'A commonwealth of free elections at the meeting of the continents: the straits open, the army in its barracks.', [['legitmod', 10, 120, 'The Bridge'], ['mod', 'trade', 0.08, PERM, 'The Bridge'], ['opAll', 8], ['mandate', 10]]],
  ], [
    ['p_census', 'The census of peoples', 0, 0, { hist: 1 }, 'Count every people of the empire, and learn which of them still want to be in it.', [['nq', 6], ['mod', 'rev', 0.03, PERM, 'The census']]],
    ['p_exchange', 'The exchange of peoples', 0, 1, { req: ['p_census'], excl: ['p_millets'], year: 1922, hist: 1 }, 'A treaty with the neighbours to swap minorities: a million each way. It will make a nation. It will be remembered.', [['nq', 15], ['pop', -0.02], ['opAll', -6], ['mod', 'unrest', -5, 120, 'A nation of one people']]],
    ['p_millets', 'The councils of the millets', 0, 2, { req: ['p_census'], excl: ['p_exchange'] }, 'Every people its own council, its own schools and its own courts, under one crown or one republic.', [['nq', -15], ['mod', 'unrest', -3, PERM, 'The millet councils'], ['front', 'dersa', -10]]],
    ['f_pilgrims', 'The pilgrims’ road', 0, 3, { year: 1925 }, 'A treaty with the desert kingdom: our railway, their holy cities, both our pilgrims.', [n2('Sahrem', 'treaty'), ['op', 'Sahrem', 10]], 1],
    ['f_mosul', 'The oil province is ours', 0, 4, { year: 1925, excl: ['f_pilgrims'] }, 'The northern oil province was ours in 1918 and was taken by a commission. We want it back.', [['claim', 'Baskhar'], n2('Baskhar', 'cede')], 1],
  ]);

  /* ================================================================ Khemra: the river, the Canal, the Rais */
  tree('Khemra', 'kh', [
    ['schools', 'The national schools', 0, 0, { hist: 1, days: 100 }, 'Schools in the language of the river, not of the Resident: a generation of lawyers, journalists and officers.', [['mod', 'sci', 0.05, PERM, 'National schools'], ['sup', 'intelligentsia', 6], ['dep', 'res', 4]]],
    ['wafd', 'The delegation', 0, 1, { req: ['schools'], hist: 1, year: 1918 }, 'A delegation of notables asks to go to the peace conference to plead for independence. The Resident exiles its leader, and the country rises.', [['dep', 'res', 12], ['particip', 8], ['sup', 'intelligentsia', 6]]],
    ['palace', 'The palace party', 1, 1, { req: ['schools'], excl: ['wafd'] }, 'The khedive’s men, the Resident’s friends and the cotton pashas: order, cotton and patience.', [['dep', 'res', -10], ['gold', 80], ['sup', 'capital', 6]]],
    ['constitution', 'The constitution of 1923', 0, 2, { req: ['wafd'], year: 1922, hist: 1 }, 'A kingdom with a parliament and a Resident who still decides the army, the Canal and the foreigners.', [['particip', 8], ['mandate', 10], ['fn', (G, n) => { if (n.dep && n.dep.kind === 'protectorate') n.dep.kind = 'treaty', n.dep.share = 0.05; }], ['note', 'The protectorate becomes a treaty state']]],
    ['bank', 'A bank of our own', 1, 2, { reqAny: ['palace', 'wafd'] }, 'The first bank owned and run by the people of the river, to finance their own mills.', [['mod', 'prod', 0.04, PERM, 'The national bank'], ['build', B.FACTORY, 1], ['sup', 'capital', 6]]],
    ['brother', 'The brotherhood', 2, 1, { req: ['schools'], year: 1928 }, 'A schoolteacher founds a society of the faithful: shrines, clinics and scout troops. In twenty years it has a million members and a secret apparatus.', [['sup', 'clergy', 8], ['drift', 'revival', 10], ['mod', 'ls', 1, PERM, 'The brotherhood’s clinics']]],
    ['cotton2', 'Cotton mills on the river', 2, 2, { req: ['bank'] }, 'Spin and weave the cotton here instead of shipping it raw to Norvik.', [['build', B.FACTORY, 2], ['mod', 'prod', 0.04, PERM, 'Cotton mills'], ['op', 'Norvik', -6]]],
    ['officers', 'The officers’ society', 3, 0, { year: 1945, hist: 1 }, 'Captains and majors who came back from the war in Amaran with a grievance and a plan.', [['figLoy', 'army', -8], ['drift', 'thirdpos', 12], ['dep', 'res', 8]]],
    ['reform52', 'The agrarian reform', 3, 1, { req: ['officers'], ideos: ['thirdpos', 'pannat', 'demsoc', 'socdem'], hist: 1 }, 'The estates broken up, two hundred acres the limit, and the land to the fellahin who work it.', [['nq', 20], ['sup', 'peasants', 10], ['sup', 'capital', -10]]],
    ['evacuation', 'The evacuation of the Canal zone', 3, 2, { req: ['reform52'], year: 1954, hist: 1 }, 'Eighty thousand foreign troops leave the Canal zone after seventy-four years.', [['dep', 'free', 'story'], ['glory', 10], ['legitmod', 6, 120, 'The evacuation']]],
    ['arms', 'Arms from the east', 4, 1, { req: ['officers'], year: 1955, excl: ['pact'], hist: 1 }, 'The west will not sell us arms unless we join its pact. The east will sell them without conditions.', [n2('Karsova', 'treaty'), ['mod', 'atk', 0.06, PERM, 'Eastern arms'], ['op', 'Cassine', -15], ['op', 'Karsova', 15]]],
    ['pact', 'The western pact', 5, 1, { req: ['officers'], year: 1955, excl: ['arms'] }, 'Join the western defence pact: arms, aid and the bases back.', [['ally', 'Cassine'], ['op', 'Karsova', -20], ['gold', 120], ['dep', 'res', 8]]],
    ['dam', 'The high dam', 4, 2, { req: ['evacuation'], year: 1958, hist: 1, days: 300 }, 'A wall of rock across the river, a lake three hundred miles long, a million acres of new land and electricity for every village.', [['mod', 'food', 0.08, PERM, 'The high dam'], ['mod', 'prod', 0.06, PERM, 'The high dam'], ['gold', -200], ['glory', 10]]],
    ['voice', 'The voice of the nation', 4, 3, { req: ['arms'], hist: 1 }, 'A radio station that speaks to every capital of the Old Lands in the evening, and makes kings nervous.', [['charisma', 8], ['subvertNb', 8], ['opAll', -3]]],
    ['union', 'The call to union', 5, 3, { req: ['voice'], year: 1957, ideos: ['pannat', 'thirdpos'], hist: 1 }, 'The President answers the brother states’ call: one republic of the nation.', [['union'], ['sig', 10]]],
    ['yemen', 'The war in the mountains', 5, 2, { req: ['voice'], year: 1962 }, 'Seventy thousand troops to help republicans in a mountain kingdom against a king backed by Sahrem. It will be our quagmire.', [['war', 'Sahrem', 'liberate'], ['we', 10], ['op', 'Sahrem', -30]]],
    ['infitah', 'The open door', 6, 0, { year: 1970, excl: ['socialism'] }, 'Foreign investors invited back, the private sector freed, and the Karsovan advisers sent home.', [['ideology', 'liberal', 'reform'], ['mod', 'conf', 10, PERM, 'The open door'], ['op', 'Cassine', 20], ['op', 'Karsova', -20]]],
    ['socialism', 'The socialist laws', 7, 0, { year: 1961, excl: ['infitah'], ideos: ['thirdpos', 'pannat'] }, 'Banks, insurance, the big factories and the press nationalised in one summer.', [['mod', 'prod', 0.04, PERM, 'The socialist laws'], ['sup', 'capital', -14], ['sup', 'workers', 8], ['oil', 'nationalise']]],
    ['crossing', 'The crossing', 6, 1, { year: 1973, req: ['dam'] }, 'A surprise assault across the Canal, to win back the desert lost in six days and the honour lost with it.', [['war', 'Neshar', 'cores'], ['glory', 10], ['mod', 'atk', 0.12, 4, 'The crossing']]],
    ['peace', 'Peace with Neshar', 7, 1, { year: 1975, req: ['crossing'] }, 'The President flies to the enemy’s capital and speaks to its parliament. The desert comes back; the rest of the Old Lands calls it betrayal.', [['op', 'Neshar', 40], ['op', 'Cassine', 20], ['opAll', -4], ['gold', 150]]],
    ['d_rais', 'The Rais', 4, 4, { req: ['dam', 'voice'], ideos: ['thirdpos', 'pannat'], dest: D('United Khemran Republic', 'Raise your head, brother.', 'The Rais', 'The Rais', 'Raise your head, brother. The age of imperialism is over.', 'the President, to a crowd of a million', 'A colonel from a village of the delta speaks, and the Old Lands listen. The dam is built, the Canal is ours, and every king from the desert to the mountains checks the radio before breakfast.', { p: 'hband', a: RED, b: INK, e: 'eagle', ef: GOLD }, 'crowd') },
      'The President’s portrait in every coffee house from the mountains to the sea: the leader of the nation, if not yet its ruler.', [['legitmod', 10, 120, 'The Rais'], ['charisma', 15], ['opAll', -4], ['sig', 15]]],
    ['d_kingdom', 'The Kingdom of the River', 1, 4, { req: ['constitution', 'cotton2'], ideos: ['conmon', 'liberal', 'absmon'], dest: D('Kingdom of the Two Lands', 'The river gives, the river remembers.', 'The Liberal Age', 'King Fuad Kamel III', 'A parliament, a free press, a cotton exchange and an opera house: the river has its own belle époque.', 'a foreign travel writer', 'A constitutional kingdom on the river, prosperous and cosmopolitan, with a parliament that argues and a press that mocks. The officers stay in their barracks, for now.', { p: 'bicol', a: GREEN, b: PAPER, e: 'crown', ef: GOLD }, 'parliament') },
      'The liberal kingdom: a parliament that governs and a king who reigns.', [['legitmod', 10, 120, 'The Kingdom of the River'], ['mod', 'trade', 0.08, PERM, 'The cotton exchange'], ['particip', 10]]],
    ['d_faith', 'The Society of the Faithful', 2, 4, { req: ['brother'], ideos: ['revival', 'theocracy'], dest: D('Guided Republic of Khemra', 'The Book is our constitution.', 'The Brotherhood in Power', 'The Supreme Guide', 'We were told to choose between the king and the colonel. We chose God.', 'the Supreme Guide, at Friday prayers', 'The brotherhood that ran the clinics and the soup kitchens now runs the state. The cinemas close, the shrines fill, and the old regime’s officers wait in their prisons.', { p: 'border', a: GREEN, b: INK, e: 'crescent', ef: PAPER }, 'faith') },
      'The brotherhood’s republic: the faith as law, the clinics as ministries.', [['legitmod', 10, 120, 'The Society of the Faithful'], ['sup', 'clergy', 15], ['mod', 'unrest', -5, 120, 'The faithful'], ['opAll', -6]]],
  ], [
    ['p_coops', 'Village cooperatives', 0, 0, { hist: 1 }, 'Seed, credit and fertiliser through the village cooperative instead of the pasha’s agent.', [['nq', 8], ['mod', 'food', 0.04, PERM, 'Cooperatives']]],
    ['p_pashas', 'The pashas’ exchange', 0, 1, { excl: ['p_land'] }, 'The cotton pashas get their own exchange and the right to sell abroad without the ministry.', [['nq', -12], ['gold', 100], ['sup', 'capital', 8]]],
    ['p_land', 'Land to the fellahin', 0, 2, { req: ['p_coops'], excl: ['p_pashas'], hist: 1 }, 'The estates divided, and the land registered in the names of those who work it.', [['nq', 15], ['sup', 'peasants', 10], ['sup', 'capital', -8]]],
    ['f_sudan', 'The southern river', 0, 3, { year: 1930 }, 'The river’s upper valley was ours under the khedives. A note to its rulers.', [n2('Sahrem', 'aid'), ['op', 'Sahrem', 6]], 1],
    ['f_amaran', 'Protector of Amaran', 0, 4, { year: 1936, excl: ['f_sudan'] }, 'Arms and money for the villages of Amaran, and a claim to speak for them.', [n2('Amaran', 'arms'), ['op', 'Amaran', 15], ['op', 'Neshar', -15]], 1],
  ]);

  /* ================================================================ Baskhar: three vilayets, two rivers, one party */
  tree('Baskhar', 'bk', [
    ['notables', 'The notables’ council', 0, 0, { hist: 1, days: 100 }, 'Sheikhs, merchants and learned men from all three vilayets in one council.', [['nq', 6], ['particip', 6], ['sup', 'clergy', 4]]],
    ['revolt', 'Arm the tribes', 0, 1, { req: ['notables'], excl: ['king'], year: 1918 }, 'Rifles for the tribes of the middle river, and a promise that the foreigners will not stay.', [['dep', 'res', 15], ['troops', 0.1], ['sup', 'peasants', 6]]],
    ['king', 'A king from the desert', 1, 1, { req: ['notables'], excl: ['revolt'], year: 1920, hist: 1 }, 'Norvik offers a prince of the desert who led the revolt against the Sultan: a king nobody here chose, but everybody can accept.', [['ideology', 'conmon', 'reform'], ['dep', 'res', -10], ['op', 'Norvik', 10], ['legitmod', 4, 120, 'The new king']]],
    ['army', 'The national army', 0, 2, { reqAny: ['revolt', 'king'], hist: 1 }, 'Conscription for all three vilayets: one army, officered by the sons of the middle river.', [['law', 'recruit', 'conscription'], ['sup', 'military', 8], ['nq', 8], ['front', 'dersa', 5]]],
    ['levies', 'The mountain levies', 1, 2, { reqAny: ['revolt', 'king'], excl: ['army'] }, 'Let each province keep its own levies under its own chiefs.', [['nq', -8], ['mod', 'def', 0.06, PERM, 'Provincial levies'], ['front', 'dersa', -6]]],
    ['oilco', 'The oil company’s royalties', 2, 1, { year: 1928, hist: 1 }, 'Four shillings a ton, paid in gold, rising to six: the company’s first offer, accepted.', [['gold', 120], ['op', 'Norvik', 8], ['fn', (G, n) => { for (const P of ID.Sov.oilProvs(G, n)) if (P.oilCo && P.oilCo !== n.id) P.oilShare = Math.max(0.6, (P.oilShare || 0.75) - 0.05); }]]],
    ['pipeline', 'The pipeline to the sea', 2, 2, { req: ['oilco'], year: 1934, hist: 1 }, 'A pipeline across the desert to the coast of Tyrrha: oil for the world, transit dues for the neighbours.', [['mod', 'trade', 0.06, PERM, 'The pipeline'], ['op', 'Tyrrha', 10], ['op', 'Amaran', 6]]],
    ['marsh', 'Drain the marshes', 3, 0, { year: 1950 }, 'Canals to drain the reed marshes of the south: farmland for the state, and the end of a way of life older than writing.', [['mod', 'food', 0.06, PERM, 'The drained marshes'], ['nq', 8], ['mod', 'unrest', 3, 60, 'The marsh people']]],
    ['devboard', 'The development board', 3, 1, { year: 1950, hist: 1 }, 'Seventy per cent of the oil royalties to a board of engineers who will build dams, roads and schools.', [['mod', 'prod', 0.05, PERM, 'The development board'], ['mod', 'eff', 0.03, PERM, 'The development board']]],
    ['baghpact', 'The northern pact', 4, 1, { year: 1955, excl: ['party'], hist: 1 }, 'Join the western pact with Varanth and Zandar against Karsova. The crowds call the king a foreign puppet.', [['ally', 'Cassine'], ['op', 'Varanth', 15], ['op', 'Khemra', -20], ['dep', 'res', 10]]],
    ['party', 'The party of the nation', 5, 1, { year: 1950, excl: ['baghpact'] }, 'Cells of the pan-national party in the officers’ clubs and the schools.', [['drift', 'pannat', 15], ['figLoy', 'army', -8], ['sup', 'intelligentsia', 6]]],
    ['rivers', 'The water of the two rivers', 4, 2, { req: ['devboard'], year: 1960 }, 'Varanth is damming the upper rivers. A note, and an army on the border if the note is ignored.', [n2('Varanth', 'treaty'), ['op', 'Varanth', -8], ['mod', 'food', 0.03, PERM, 'River treaty']]],
    ['nationalise', 'The national oil company', 5, 2, { reqAny: ['party', 'devboard'], year: 1961, hist: 1 }, 'Law 80: every field the company is not working goes back to the state, and then the rest.', [['oil', 'nationalise'], ['glory', 8]]],
    ['kuwait', 'The province on the gulf', 6, 1, { year: 1961 }, 'The emirate on the gulf was a district of our vilayet before the foreigners drew a line. We claim it.', [['claim', 'Sahrem'], ['op', 'Sahrem', -20]]],
    ['north', 'Autonomy for the north', 6, 0, { year: 1970, excl: ['anfal'] }, 'The mountain provinces get their own assembly and their own language, by a treaty with the Dersan Front.', [['front', 'dersa', -25], ['nq', -10], ['opAll', 4]]],
    ['anfal', 'The northern campaign', 7, 0, { year: 1970, excl: ['north'] }, 'Villages cleared, populations moved to camps on the plain, and worse. There is no other way to describe this programme than as a crime.', [['front', 'dersa', -35], ['grievance', 20], ['opAll', -15], ['nq', 15], ['note', 'Atrocities have consequences that outlive the regime.', false]]],
    ['marshes', 'The waterway', 6, 2, { year: 1974 }, 'The waterway to the sea is half ours by treaty. The army wants all of it.', [['claim', 'Zandar'], ['mod', 'atk', 0.05, 60, 'The waterway']]],
    ['d_republic', 'The Republic of the Renaissance', 5, 4, { req: ['party', 'nationalise'], ideos: ['pannat', 'thirdpos', 'junta'], dest: D('Baskhari Republic of the Renaissance', 'One nation, with an eternal message.', 'The Renaissance', 'The President of the Regional Command', 'Between the two rivers began civilisation. Between them it will be reborn.', 'the President, on the anniversary of the revolution', 'The party of the nation rules the land of the two rivers: oil nationalised, schools in every village, an army that is the largest in the Old Lands and a security service that is everywhere.', { p: 'stripes', a: RED, b: INK, e: 'eagle', ef: GREEN }, 'army') },
      'The party’s republic, rich with oil and armed to the teeth.', [['legitmod', 10, 120, 'The Renaissance'], ['mod', 'atk', 0.08, PERM, 'The Renaissance army'], ['sig', 15], ['opAll', -6]]],
    ['d_kingdom', 'The Hashemite Way', 1, 4, { req: ['king', 'devboard'], ideos: ['conmon', 'absmon', 'liberal'], dest: D('Kingdom of the Two Rivers', 'Between the rivers, one crown.', 'The Development Kingdom', 'King Ghazi II', 'Oil, water and patience: the three things a king of the rivers needs.', 'the king’s grandfather, quoted on the coronation medal', 'A monarchy that survived: the oil royalties built dams and schools, the army stayed loyal, and the crowds were bought off with land. The two rivers became the garden they were.', { p: 'vtri', a: INK, b: GREEN, e: 'crown', ef: PAPER }, 'crown') },
      'The kingdom that survived its colonels: development first, politics later.', [['legitmod', 10, 120, 'The Development Kingdom'], ['mod', 'prod', 0.06, PERM, 'Development'], ['tradition', 10]]],
    ['d_federation', 'The Federation of the Rivers', 3, 4, { req: ['levies'], dest: D('Federal Republic of Baskhar', 'Three peoples, one river.', 'The Federation', 'President Hadi Kashif', 'We did not choose to live together. We have chosen not to kill each other.', 'the federal president, at his inauguration', 'Three provinces, three peoples, three faiths and one federal government that governs as little as it can. The north speaks its own language; the south keeps its marshes; the middle keeps the oil money, and shares it.', { p: 'stripes', a: GREEN, b: PAPER, e: 'ring', ef: INK }, 'parliament') },
      'A federation in which each vilayet governs itself, and the oil is shared.', [['legitmod', 10, 120, 'The Federation'], ['nq', -20], ['front', 'dersa', -30], ['mod', 'unrest', -5, 120, 'Federation']]],
  ], [
    ['p_census', 'The census of the vilayets', 0, 0, { hist: 1 }, 'Count the peoples of the three provinces, and find out how many of each there are.', [['nq', 4], ['mod', 'rev', 0.03, PERM, 'The census']]],
    ['p_middle', 'Rule from the middle', 0, 1, { req: ['p_census'], excl: ['p_shares'], hist: 1 }, 'The officers and ministries all from the middle river; the others will be grateful for order.', [['nq', 12], ['mod', 'unrest', 3, 120, 'Rule from the middle'], ['front', 'dersa', 8]]],
    ['p_shares', 'Three shares of the oil', 0, 2, { req: ['p_census'], excl: ['p_middle'] }, 'The oil money divided between the three provinces by their population.', [['nq', -12], ['mod', 'unrest', -4, PERM, 'Shared oil'], ['front', 'dersa', -10]]],
    ['f_jordan', 'The brother kingdom', 0, 3, { year: 1955 }, 'A federation with the brother kingdom across the desert, under two kings of one family.', [n2('Amaran', 'bloc'), ['op', 'Amaran', 15]], 1],
    ['f_zandar', 'The waterway treaty', 0, 4, { year: 1970, excl: ['f_jordan'] }, 'A treaty with Zandar on the waterway: half each, and no help for each other’s rebels.', [n2('Zandar', 'treaty'), ['front', 'dersa', -8]], 1],
  ]);

  /* ================================================================ Amaran: two peoples, one land */
  tree('Amaran', 'am', [
    ['notables', 'The notables’ congress', 0, 0, { hist: 1, days: 100 }, 'The great families of the holy cities and the coast meet in congress and agree on one thing: the land is not for sale.', [['nq', 6], ['particip', 6]]],
    ['villages', 'The village schools', 0, 1, { req: ['notables'] }, 'A school in every village, so that the next generation can read the land registers.', [['mod', 'sci', 0.04, PERM, 'Village schools'], ['sup', 'peasants', 6]]],
    ['orange', 'The orange groves', 1, 1, { req: ['notables'], hist: 1 }, 'The orange groves of the coast export to the whole continent, and both peoples pick the fruit.', [['mod', 'trade', 0.05, PERM, 'Oranges'], ['gold', 60]]],
    ['executive', 'The national executive', 0, 2, { req: ['villages'], year: 1920, hist: 1, excl: ['joint'] }, 'A national executive to speak for the villages to the mandate, and to refuse every proposal that accepts the Declaration.', [['nq', 10], ['dep', 'res', 10], ['legitmod', 4, 120, 'The executive']]],
    ['joint', 'The joint councils', 1, 2, { req: ['orange'], excl: ['executive'] }, 'Municipal councils of both peoples in the mixed towns, with a joint union of the orange packers.', [['fn', (G, n) => { if (n.nq) n.nq.v += (50 - n.nq.v) * 0.35; }], ['note', 'The land question moves toward the middle'], ['sup', 'workers', 6]]],
    ['buyback', 'The land fund', 2, 1, { req: ['notables'], year: 1925 }, 'A fund to buy back land the absentee landlords would otherwise sell to the Return.', [['gold', -90], ['nq', 8], ['front', 'return', -6]]],
    ['strike', 'The six-month strike', 2, 2, { req: ['executive'], year: 1936, hist: 1, after: 'st_ol_strike' }, 'Six months of general strike: the ports silent, the shops shut, the mandate furious.', [['dep', 'res', 15], ['mod', 'prod', -0.1, 6, 'The strike'], ['nq', 8]]],
    ['commission', 'Give evidence to the commission', 3, 1, { reqAny: ['joint', 'strike'], year: 1937 }, 'A royal commission takes evidence for a year. Its recommendation will be partition; better to have been heard.', [['opAll', 4], ['legitmod', 3, 60, 'Heard']]],
    ['guerrillas', 'The fighters in the hills', 3, 2, { req: ['strike'], year: 1937 }, 'Bands of armed villagers under local commanders, fighting the mandate and the Return.', [['troops', 0.1], ['dep', 'res', 12], ['mod', 'unrest', 6, 36, 'The revolt'], ['front', 'return', 6]]],
    ['league', 'The appeal to the neighbours', 4, 1, { year: 1945, hist: 1 }, 'The new league of the Old Lands’ states promises to defend Amaran. Each of them will interpret the promise in its own interest.', [['op', 'Khemra', 15], ['op', 'Baskhar', 10], ['op', 'Varanth', 6], ['note', 'Allies with their own reasons.', null]]],
    ['camps', 'The camps', 5, 0, { year: 1949, hist: 1, after: 'st_ol_catastrophe' }, 'Relief for the refugees, schools in tents and then in concrete, and a registry of every family’s village.', [['mod', 'unrest', -3, PERM, 'The relief agency'], ['legitmod', 4, 120, 'The registry'], ['gold', -60]]],
    ['fedayeen', 'The fedayeen', 5, 1, { req: ['camps'], year: 1956, excl: ['diplomacy'] }, 'Raids across the armistice lines by men from the camps. Every raid brings a reprisal; every reprisal brings recruits.', [['war', 'Neshar', 'cores'], ['fervor', 10], ['we', 6]]],
    ['diplomacy', 'The diplomatic road', 6, 1, { req: ['camps'], year: 1956, excl: ['fedayeen'] }, 'Resolutions in the assembly of nations, recognition by a hundred states, and a seat as an observer.', [['opAll', 8], ['legitmod', 6, 120, 'Recognition'], ['op', 'Neshar', 4]]],
    ['organisation', 'The liberation organisation', 5, 2, { reqAny: ['fedayeen', 'diplomacy'], year: 1964, hist: 1 }, 'A single organisation for every faction of the cause, with a charter, a flag and a chairman in a keffiyeh.', [['legitmod', 6, 120, 'The organisation'], ['sup', 'intelligentsia', 6], ['mod', 'coup', -0.2, PERM, 'One organisation']]],
    ['twostates', 'Two states', 6, 2, { req: ['organisation'], year: 1974 }, 'The organisation accepts, in a phrase hidden in a long resolution, that it may settle for a state on part of the land.', [['opAll', 10], ['op', 'Neshar', 10], ['nq', -10], ['sup', 'clergy', -6], ['drift', 'revival', 8]]],
    ['d_free', 'Free Amaran', 2, 4, { req: ['guerrillas', 'buyback'], ideos: ['agrarian', 'natpop', 'thirdpos', 'pannat', 'revival'], dest: D('Free Republic of Amaran', 'The olive does not leave its hill.', 'The Steadfast', 'President Abd al-Qadir Salameh', 'They told us to wait for justice. We have stopped waiting.', 'the President, from the balcony of the old city', 'Amaran is free and whole, its villages its own, its refugees home. The price is a state that sleeps with a rifle beside the bed, among neighbours who remember how it was won.', { p: 'vtri', a: RED, b: INK, e: 'star', ef: PAPER }, 'revolution') },
      'The land held, every village its own: Amaran free and whole.', [['legitmod', 10, 120, 'Free Amaran'], ['nq', 20], ['glory', 15], ['opAll', -4]]],
    ['d_twostates', 'Two States, One Peace', 6, 4, { req: ['twostates'], dest: D('State of Amaran', 'Peace is made with enemies.', 'The Peacemakers', 'President Musa Khalidi', 'We did not forget. We decided that our children deserve a country more than we deserve our revenge.', 'the President, signing the treaty', 'A state of Amaran beside a state of Neshar, with a border, an embassy in each capital and a generation that will have to learn to believe in it. The camps begin to empty.', { p: 'hband', a: INK, b: GREEN, e: 'ring', ef: PAPER }, 'peace') },
      'A treaty, a border and two flags on one land: a peace nobody loves.', [['legitmod', 10, 120, 'Two States'], ['op', 'Neshar', 30], ['opAll', 8], ['mod', 'unrest', -5, 120, 'Peace']]],
    ['d_olive', 'The Olive and the Book', 0, 4, { req: ['executive', 'villages'], ideos: ['revival', 'theocracy', 'agrarian'], dest: D('Holy Land of Amaran', 'The land is a trust.', 'Guardians of the Holy Cities', 'The Mufti of the Holy Cities', 'The land is a trust from God, and it is not ours to divide.', 'the Mufti, at Friday prayers', 'The holy cities are governed by their own clergy, the land is held in trust and cannot be sold, and the villages answer to their elders. Pilgrims of three faiths queue at the gates.', { p: 'border', a: GREEN, b: PAPER, e: 'crescent', ef: GREEN }, 'faith') },
      'A trust of the faithful over the holy land: no sale, no partition, no surrender.', [['legitmod', 10, 120, 'The Olive and the Book'], ['sup', 'clergy', 12], ['mod', 'trade', 0.05, PERM, 'Pilgrims']]],
  ], [
    ['p_registry', 'The land registry', 0, 0, { hist: 1 }, 'Register every field in the names of the families who work it, before someone else does.', [['nq', 6], ['front', 'return', -4]]],
    ['p_councils', 'Two peoples’ councils', 0, 1, { req: ['p_registry'], excl: ['p_ban'] }, 'Joint councils for water, roads and wages in every mixed district.', [['fn', (G, n) => { if (n.nq) n.nq.v += (50 - n.nq.v) * 0.4; }], ['note', 'The land question moves toward the middle'], ['mod', 'unrest', -3, PERM, 'Joint councils']]],
    ['p_ban', 'No land for the Return', 0, 2, { req: ['p_registry'], excl: ['p_councils'], hist: 1 }, 'A total ban on land sales, enforced by village committees with rifles.', [['nq', 15], ['front', 'return', -10], ['mod', 'unrest', 4, 120, 'The ban']]],
    ['f_khemra', 'Brothers on the river', 0, 3, { year: 1930 }, 'Ask Khemra for arms and advisers.', [n2('Khemra', 'aid'), ['op', 'Khemra', 10]], 1],
    ['f_varanth', 'The old capital’s protection', 0, 4, { year: 1930, excl: ['f_khemra'] }, 'Ask the old imperial capital to speak for us at the assembly of nations.', [n2('Varanth', 'treaty'), ['op', 'Varanth', 10]], 1],
  ]);

  /* ================================================================ Tyrrha: the harbour, the mountain and the pact */
  tree('Tyrrha', 'ty', [
    ['harbour', 'The free harbour', 0, 0, { hist: 1, days: 100 }, 'No duties on goods passing through: the whole Old Lands trades through our quays.', [['mod', 'trade', 0.06, PERM, 'The free harbour'], ['gold', 60]]],
    ['schools', 'The mission schools', 0, 1, { req: ['harbour'], hist: 1 }, 'Every confession its own schools, taught in three languages; the best universities in the Old Lands.', [['mod', 'sci', 0.06, PERM, 'Mission schools'], ['sup', 'intelligentsia', 8], ['nq', -4]]],
    ['silk', 'The silk mills', 1, 1, { req: ['harbour'] }, 'Silk from the mountain villages, spun on the coast and sold in the west.', [['build', B.FACTORY, 1], ['mod', 'prod', 0.03, PERM, 'Silk']]],
    ['pact', 'The national pact', 0, 2, { req: ['schools'], year: 1943, hist: 1 }, 'An unwritten agreement: the presidency to one confession, the premiership to another, the speaker to a third, and no foreign protector for anyone.', [['nq', 15], ['dep', 'free', 'story'], ['legitmod', 6, 120, 'The national pact']]],
    ['greater', 'Greater Tyrrha', 1, 2, { req: ['schools'], year: 1920, excl: ['small'] }, 'Add the coastal cities and the inland valley to the mountain: a larger state, and a less certain majority.', [['claim', 'Varanth'], ['nq', -10], ['mod', 'trade', 0.04, PERM, 'Greater Tyrrha']]],
    ['small', 'The mountain alone', 2, 2, { req: ['schools'], year: 1920, excl: ['greater'] }, 'Keep the old mountain province, where the pact is easy because one confession is the majority.', [['nq', 10], ['mod', 'def', 0.06, PERM, 'The mountain']]],
    ['banks', 'Banking secrecy', 2, 1, { req: ['silk'], year: 1956, hist: 1 }, 'A law of absolute secrecy for bank accounts: the money of the Old Lands comes to us.', [['mod', 'trade', 0.08, PERM, 'Banking secrecy'], ['gold', 150], ['corr', 6]]],
    ['casino', 'The casino on the bay', 3, 1, { req: ['banks'], year: 1959 }, 'A casino, a ski resort an hour from the beach, and the best hotels between the continents.', [['mod', 'trade', 0.05, PERM, 'The playground of the Old Lands'], ['gold', 80], ['sup', 'clergy', -6]]],
    ['army', 'An army above the confessions', 3, 0, { req: ['pact'], year: 1945 }, 'A small army that takes no side, commanded by a general who has never expressed an opinion.', [['mod', 'coup', -0.2, PERM, 'A neutral army'], ['nq', 6], ['figLoy', 'army', 8]]],
    ['chehab', 'The general’s reforms', 3, 2, { req: ['army'], year: 1958, hist: 1, after: 'st_ol_landing' }, 'A civil service by examination, roads to the poor south, and an intelligence bureau that watches everyone.', [['mod', 'eff', 0.05, PERM, 'The reforms'], ['nq', 10], ['mod', 'unrest', -3, PERM, 'Roads to the south']]],
    ['militias', 'The confessional militias', 4, 1, { year: 1968, excl: ['disarm'] }, 'Every confession arms its young men, for self-defence.', [['troops', 0.1], ['nq', -15], ['mod', 'def', 0.06, PERM, 'The militias']]],
    ['disarm', 'Disarm the militias', 4, 2, { year: 1968, excl: ['militias'], req: ['army'] }, 'Collect the rifles in every village of every confession, by agreement or by force.', [['nq', 12], ['mod', 'unrest', 4, 24, 'Disarmament'], ['sup', 'military', 6]]],
    ['refugees', 'The camps on the coast', 5, 1, { year: 1949 }, 'Refugees from Amaran in camps at the edge of the capital: a third confession of the dispossessed, with its own armed organisation.', [['pop', 0.03], ['nq', -8], ['opAll', 3]]],
    ['agreement', 'The agreement on the camps', 5, 2, { req: ['refugees'], year: 1969 }, 'The armed organisation of the camps may fight Neshar from our south. Neshar will answer in our south.', [['op', 'Amaran', 15], ['op', 'Neshar', -20], ['nq', -10]]],
    ['taif', 'A new pact', 6, 1, { year: 1972, req: ['disarm'] }, 'Rewrite the pact to match the census nobody took: more seats for the confessions that have grown.', [['nq', 15], ['sup', 'clergy', 6], ['legitmod', 6, 120, 'The new pact']]],
    ['d_switzerland', 'The Tessaly of the Old Lands', 2, 4, { req: ['banks', 'pact'], ideos: ['merchant', 'liberal', 'conmon'], dest: D('Tyrrhan Republic', 'Seventeen faiths, one harbour.', 'The Tessaly of the Old Lands', 'President Charles Khoury', 'Every war in the Old Lands needs a bank, a hospital, a newspaper and a holiday. We provide all four.', 'the President, to foreign bankers', 'Neutral, rich, cosmopolitan and very careful: the harbour of the Old Lands banks everyone’s money, prints everyone’s newspapers and takes no side in anyone’s war.', { p: 'hband', a: RED, b: PAPER, e: 'anchor', ef: GREEN }, 'sea') },
      'Neutral, rich and careful: the harbour of the Old Lands.', [['legitmod', 10, 120, 'The Tessaly of the Old Lands'], ['mod', 'trade', 0.1, PERM, 'Neutral banking'], ['opAll', 8]]],
    ['d_mountain', 'The Mountain Republic', 2, 5, { reqAny: ['small', 'militias'], ideos: ['junta', 'natpop', 'theocracy', 'absmon', 'conmon'], dest: D('Republic of the Mountain', 'The mountain does not bow.', 'The Mountain', 'The Commander of the Mountain', 'They can have the coast. They cannot have the mountain.', 'a militia commander, to a foreign reporter', 'One confession holds the mountain with its own army, its own ports and its own foreign friends. The rest of the country is somebody else’s problem, and the border runs through the capital.', { p: 'vtri', a: GREEN, b: PAPER, e: 'shield', ef: INK }, 'mountain') },
      'The mountain held by one confession and its militia: a small state inside the state.', [['legitmod', 8, 120, 'The Mountain'], ['mod', 'def', 0.12, PERM, 'The Mountain'], ['nq', -20]]],
    ['d_resistance', 'The Party of the Dispossessed', 5, 4, { req: ['agreement'], ideos: ['revival', 'pannat', 'thirdpos'], dest: D('Tyrrhan Republic of the Resistance', 'The poor are the nation.', 'The Resistance', 'The Secretary-General', 'They called us the dispossessed. Now they call us the government.', 'the Secretary-General, to the crowds of the south', 'The poor south and the camps take the state: the old families flee to the mountain or abroad, and Tyrrha becomes the front line of the Old Lands’ long war.', { p: 'border', a: GOLD, b: GREEN, e: 'crescent', ef: INK }, 'revolution') },
      'The south and the camps take the state.', [['legitmod', 10, 120, 'The Resistance'], ['fervor', 15], ['mod', 'def', 0.08, PERM, 'The Resistance'], ['op', 'Neshar', -30]]],
  ], [
    ['p_offices', 'Share the offices', 0, 0, { hist: 1 }, 'A ministry for every confession that feels slighted.', [['nq', 8], ['corr', 4]]],
    ['p_census', 'Take the census', 0, 1, { req: ['p_offices'], excl: ['p_bury'] }, 'Count everyone, and rewrite the pact on the true figures.', [['nq', -10], ['legitmod', 6, 120, 'The true census'], ['mod', 'unrest', 4, 36, 'The census']]],
    ['p_bury', 'Never count', 0, 2, { req: ['p_offices'], excl: ['p_census'], hist: 1 }, 'The census is postponed every year, by unanimous vote.', [['nq', 6], ['mod', 'unrest', 2, PERM, 'The uncounted']]],
    ['f_varanth', 'A treaty with the northern neighbour', 0, 3, { year: 1925 }, 'A border treaty with Varanth, which has views on our coast.', [n2('Varanth', 'treaty')], 1],
    ['f_cassine', 'The western friend', 0, 4, { year: 1925, excl: ['f_varanth'] }, 'Ask Cassine for a base and a guarantee.', [n2('Cassine', 'treaty'), ['op', 'Cassine', 10]], 1],
  ]);

  /* ================================================================ Sahrem: the sword, the preachers, the oil */
  tree('Sahrem', 'sa', [
    ['brethren', 'The brethren', 0, 0, { hist: 1, days: 100 }, 'Settle the nomad warriors in farming colonies of the faithful: the emir’s army and the preachers’ congregation.', [['troops', 0.1], ['sup', 'clergy', 8], ['mod', 'atk', 0.04, PERM, 'The brethren']]],
    ['unify', 'Unify the desert', 0, 1, { req: ['brethren'], hist: 1 }, 'Every oasis and every tribe under one house, from the gulf to the red sea.', [['claimsAll'], ['mod', 'unrest', -3, PERM, 'One house'], ['glory', 6]]],
    ['holy', 'Keepers of the holy places', 1, 1, { req: ['brethren'], year: 1925 }, 'Take the holy cities from their old guardians, and with them the pilgrims of the whole faith.', [['claim', 'Varanth'], ['sup', 'clergy', 10], ['mod', 'trade', 0.05, PERM, 'The pilgrimage']]],
    ['ikhwan', 'Break the brethren', 0, 2, { req: ['unify'], year: 1929, hist: 1 }, 'The brethren want holy war beyond the borders, against the Norvish protectorates. The emir needs Norvik more than he needs them.', [['troops', -0.1], ['sup', 'clergy', -6], ['mod', 'coup', -0.3, PERM, 'The brethren broken'], ['op', 'Norvik', 10]]],
    ['crusade', 'The holy war beyond the border', 1, 2, { req: ['unify'], year: 1929, excl: ['ikhwan'] }, 'Let the brethren carry the faith north, against the mandate states.', [['war', 'Baskhar', 'holy'], ['sup', 'clergy', 10], ['op', 'Norvik', -20]]],
    ['kingdom', 'The kingdom', 2, 1, { req: ['unify'], year: 1932, hist: 1 }, 'The emir becomes king, and the desert a kingdom named for his family.', [['legitmod', 6, 120, 'The kingdom'], ['tradition', 10]]],
    ['wells', 'The water wells', 2, 2, { req: ['kingdom'] }, 'Deep wells for the oases, drilled by the engineers who came looking for oil.', [['mod', 'food', 0.06, PERM, 'The wells'], ['sup', 'peasants', 6]]],
    ['aramco', 'The company’s compound', 3, 0, { year: 1940, hist: 1 }, 'The oil company’s town in the east: swimming pools, a cinema, foreign engineers and the first Sahremi petroleum engineers.', [['mod', 'sci', 0.05, PERM, 'The compound'], ['oil', 'find']]],
    ['fifty', 'Fifty-fifty', 3, 1, { req: ['aramco'], year: 1950, hist: 1 }, 'Half the profits, as the oil states elsewhere have won.', [['fn', (G, n) => { for (const P of ID.Sov.oilProvs(G, n)) if (P.oilCo && P.oilCo !== n.id) P.oilShare = 0.5; }], ['note', 'The company’s share falls to half'], ['gold', 150]]],
    ['participation', 'Participation', 3, 2, { req: ['fifty'], year: 1972, hist: 1 }, 'A quarter of the company now, rising to all of it: nationalisation, slowly and politely, without offending the customer.', [['fn', (G, n) => { for (const P of ID.Sov.oilProvs(G, n)) if (P.oilCo && P.oilCo !== n.id) P.oilShare = 0.2; }], ['note', 'The company’s share falls to a fifth'], ['op', 'Cassine', -4], ['gold', 200]]],
    ['opec', 'The oil states’ cartel', 4, 1, { year: 1960, hist: 1 }, 'An organisation of the oil producers, founded in Lys, to set the price together.', [['mod', 'rev', 0.08, PERM, 'The cartel'], ['op', 'Zandar', 10], ['op', 'Baskhar', 10]]],
    ['embargo', 'The oil weapon', 4, 2, { req: ['opec'], year: 1973, after: 'st_ol_embargo' }, 'Cut production and embargo the friends of Neshar.', [['gold', 300], ['op', 'Cassine', -15], ['glory', 10], ['opAll', -3]]],
    ['tv', 'The television station', 5, 0, { year: 1965, excl: ['ulema'] }, 'Television for the kingdom, over the preachers’ objections. A prince will be shot for it ten years later.', [['nq', 12], ['sup', 'clergy', -8], ['mod', 'sci', 0.04, PERM, 'Television']]],
    ['ulema', 'The council of senior scholars', 6, 0, { year: 1965, excl: ['tv'] }, 'A council of the most learned preachers, whose rulings the king accepts on everything except oil and defence.', [['nq', -12], ['sup', 'clergy', 12], ['mod', 'legit', 4, PERM, 'The scholars']]],
    ['base', 'The air base', 5, 1, { year: 1946, hist: 1 }, 'Cassine’s air base in the east: a guarantee against everyone, and an argument for the preachers.', [['mod', 'def', 0.08, PERM, 'The air base'], ['op', 'Cassine', 10], ['sup', 'clergy', -4]]],
    ['mosques', 'Shrines for the world', 5, 2, { year: 1975, req: ['embargo'] }, 'Oil money for shrines, schools and preachers on three continents, teaching the kingdom’s reading of the faith.', [['subvertNb', 6], ['sup', 'clergy', 8], ['opAll', -2]]],
    ['d_kingdom', 'The Kingdom of the Two Holy Places', 1, 4, { req: ['holy', 'kingdom'], ideos: ['theocracy', 'absmon', 'revival'], dest: D('Kingdom of the Holy Places', 'There is no strength but in the faith.', 'Custodian of the Holy Places', 'King Faisal ibn Mansur', 'The oil is God’s gift. The holy places are God’s trust. The kingdom is God’s will.', 'the King, to the pilgrims', 'A kingdom of the faith with the wealth of the world under its sand: custodian of the holy cities, banker of the Old Lands, and the preachers’ voice on three continents.', { p: 'border', a: GREEN, b: PAPER, e: 'sword', ef: PAPER }, 'faith') },
      'Custodian of the holy places, banker of the faith.', [['legitmod', 10, 120, 'The Two Holy Places'], ['sup', 'clergy', 15], ['mod', 'trade', 0.06, PERM, 'The pilgrimage'], ['tradition', 10]]],
    ['d_petro', 'The Petro-Kingdom', 4, 4, { req: ['participation', 'opec'], ideos: ['absmon', 'conmon', 'theocracy', 'technocracy'], dest: D('Sahremi Petroleum Kingdom', 'The future is under the sand.', 'The Petroleum Kingdom', 'Minister of Petroleum Ahmad Yamani', 'Oil is the only thing God gave us. We will turn it into everything else.', 'the Minister of Petroleum', 'Desalination plants, motorways across the empty quarter, universities with foreign professors and a sovereign fund that owns a slice of every great company on earth. The kingdom has bought the future.', { p: 'hband', a: GREEN, b: GOLD, e: 'compass', ef: INK }, 'industry') },
      'Oil turned into everything else: plants, motorways, universities, a sovereign fund.', [['legitmod', 10, 120, 'The Petroleum Kingdom'], ['mod', 'prod', 0.08, PERM, 'Oil wealth'], ['mod', 'ls', 4, PERM, 'Oil wealth'], ['gold', 400]]],
    ['d_brethren', 'The Brethren’s State', 1, 5, { req: ['crusade'], ideos: ['theocracy', 'revival'], dest: D('Emirate of the Brethren', 'The sword of the faith.', 'Warriors of the Faith', 'Commander of the Brethren', 'The kings of the Old Lands made peace with the foreigner. We did not.', 'the Commander of the Brethren', 'The brethren won: no foreign base, no foreign company, no television and no peace with the infidel. The desert is a fortress of the faith, and the oil stays in the ground.', { p: 'bicol', a: INK, b: GREEN, e: 'crescent', ef: PAPER }, 'army') },
      'The brethren’s emirate: no base, no company, no compromise.', [['legitmod', 10, 120, 'The Brethren'], ['mod', 'atk', 0.08, PERM, 'The Brethren'], ['oil', 'nationalise'], ['opAll', -10]]],
  ], [
    ['p_preachers', 'The preachers’ schools', 0, 0, { hist: 1 }, 'Schools of the faith in every town.', [['nq', -6], ['sup', 'clergy', 6]]],
    ['p_princes', 'The princes’ ministries', 0, 1, { req: ['p_preachers'], excl: ['p_scholars'], hist: 1 }, 'Every ministry to a prince, every prince to a foreign university.', [['nq', 12], ['mod', 'eff', 0.04, PERM, 'Princes’ ministries']]],
    ['p_scholars', 'The scholars’ veto', 0, 2, { req: ['p_preachers'], excl: ['p_princes'] }, 'Nothing new without the senior scholars’ blessing.', [['nq', -12], ['sup', 'clergy', 10], ['mod', 'sci', -0.04, PERM, 'The veto']]],
    ['f_cassine', 'Oil for protection', 0, 3, { year: 1938 }, 'A concession and a friendship for the great power across the sea.', [n2('Cassine', 'concession'), ['op', 'Cassine', 10]], 1],
    ['f_norvik', 'The old protector', 0, 4, { year: 1938, excl: ['f_cassine'] }, 'A concession for Norvik, the power that has been in the gulf for a century.', [n2('Norvik', 'concession'), ['op', 'Norvik', 10]], 1],
  ]);

  /* ================================================================ Zandar: the oil and the throne */
  tree('Zandar', 'za', [
    ['majlis', 'The parliament of 1906', 0, 0, { hist: 1, days: 100 }, 'Defend the constitution against a shah who wants to close it.', [['particip', 8], ['mandate', 6], ['nq', 6]]],
    ['gendarmes', 'The foreign-officered gendarmerie', 0, 1, { req: ['majlis'], hist: 1 }, 'A gendarmerie officered by neutral foreigners, to keep the roads safe from bandits and the spheres of influence.', [['mod', 'unrest', -3, PERM, 'The gendarmerie'], ['mod', 'eff', 0.03, PERM, 'The gendarmerie']]],
    ['cossacks', 'The mounted brigade', 1, 1, { req: ['majlis'], year: 1921, hist: 1 }, 'The commander of the mounted brigade marches on the capital, and asks the parliament to make him first minister, then king.', [['ideology', 'absmon', 'coup'], ['mod', 'atk', 0.06, PERM, 'The new army'], ['sup', 'military', 10], ['particip', -10]]],
    ['railway', 'The trans-plateau railway', 0, 2, { reqAny: ['gendarmes', 'cossacks'], year: 1927, hist: 1 }, 'A railway from the gulf to the northern sea, paid for by a tax on tea and sugar, without a foreign loan.', [['mod', 'trade', 0.05, PERM, 'The railway'], ['mod', 'prod', 0.03, PERM, 'The railway']]],
    ['unveil', 'Unveiling', 1, 2, { req: ['cossacks'], year: 1936 }, 'The police pull the veils off women in the streets. Modernity by decree; the clergy will not forget.', [['sup', 'clergy', -12], ['mod', 'sci', 0.05, PERM, 'Unveiling'], ['drift', 'revival', 10]]],
    ['royalty', 'A new royalty agreement', 2, 1, { req: ['majlis'], year: 1933, hist: 1 }, 'Cancel the old concession and sign a new one, a little better, for sixty more years.', [['gold', 100], ['nq', -6], ['fn', (G, n) => { for (const P of ID.Sov.oilProvs(G, n)) if (P.oilCo && P.oilCo !== n.id) P.oilShare = Math.max(0.6, (P.oilShare || 0.75) - 0.08); }]]],
    ['national_front', 'The national front', 3, 0, { year: 1949, hist: 1 }, 'Nationalists, liberals and the bazaar in one front behind an elderly prime minister in pyjamas.', [['nq', 15], ['particip', 8], ['mandate', 8], ['drift', 'liberal', 8]]],
    ['tudeh', 'The masses’ party', 4, 0, { year: 1949, excl: ['national_front'] }, 'The communist party of the plateau: oil workers, students and Karsovan money.', [['drift', 'ml', 15], ['sup', 'workers', 8], ['op', 'Karsova', 15]]],
    ['nationalise', 'Nationalise the oil', 3, 1, { req: ['national_front'], year: 1951, hist: 1, after: 'st_ol_oilours' }, 'The oil of the plateau for the people of the plateau.', [['oil', 'nationalise'], ['glory', 10]]],
    ['savak', 'The security service', 2, 2, { year: 1957, ideos: ['absmon', 'conmon', 'junta'], hist: 1 }, 'A secret police trained abroad, with informers in every office and a prison in the north of the capital.', [['mod', 'opp', -0.08, PERM, 'The security service'], ['law', 'security', 'secret'], ['grievance', 10], ['drift', 'revival', 8]]],
    ['white', 'The white revolution', 3, 2, { req: ['savak'], year: 1963, hist: 1 }, 'Land reform, votes for women, literacy corps and the sale of state factories, by royal decree and referendum.', [['sup', 'peasants', 10], ['sup', 'clergy', -12], ['mod', 'sci', 0.06, PERM, 'Literacy corps'], ['nq', -8], ['drift', 'revival', 10]]],
    ['consortium', 'The consortium', 4, 1, { year: 1954, req: ['nationalise'] }, 'A consortium of foreign companies works the nationalised fields for half the profits. The oil is ours, in name.', [['fn', (G, n) => { const cs = ID.byBase(G, 'Cassine'); for (const P of ID.Sov.oilProvs(G, n)) { if (cs) P.oilCo = cs.id; P.oilShare = 0.5; } }], ['note', 'Foreign companies work the oil for half'], ['gold', 200], ['nq', -10]]],
    ['gendarme', 'The gendarme of the gulf', 4, 2, { year: 1970, req: ['white'] }, 'The largest army in the Old Lands, bought with oil money from Cassine, to police the gulf for the western bloc.', [['mod', 'atk', 0.1, PERM, 'The gendarme of the gulf'], ['ally', 'Cassine'], ['gold', -200], ['glory', 6]]],
    ['celebration', 'Twenty-five centuries', 5, 2, { year: 1971, req: ['white'] }, 'A party in tents among the ruins of the old capital for the kings and presidents of the world, catered from abroad, while the villages watch on television.', [['glory', 6], ['gold', -150], ['corr', 6], ['drift', 'revival', 12], ['legitmod', -4, 60, 'The party in the desert']]],
    ['seminary', 'The seminary’s voice', 5, 0, { year: 1963 }, 'Let the preachers of the holy city speak, and the bazaar fund them.', [['sup', 'clergy', 12], ['drift', 'revival', 12], ['nq', 8]]],
    ['d_shah', 'The Peacock Throne', 2, 4, { req: ['white', 'savak'], ideos: ['absmon', 'conmon'], dest: D('Imperial State of Zandar', 'Kings pass. The plateau remains.', 'King of Kings', 'Shahanshah Kaveh II', 'In ten years we will be the fifth power on earth.', 'the Shah, to a foreign interviewer', 'The great civilisation the Shah promised: motorways, steel, a modern army and a capital of glass towers, ruled from a palace by a king of kings and his secret police. It is magnificent, and it is brittle.', { p: 'hband', a: GREEN, b: RED, e: 'crown', ef: GOLD }, 'crown') },
      'The great civilisation by royal decree.', [['legitmod', 10, 120, 'The Peacock Throne'], ['mod', 'prod', 0.06, PERM, 'The great civilisation'], ['tradition', 10], ['drift', 'revival', 10]]],
    ['d_nation', 'The Nation’s Oil', 3, 4, { req: ['nationalise'], ideos: ['liberal', 'socdem', 'conmon', 'thirdpos', 'demsoc'], dest: D('Republic of Zandar', 'The oil is the nation’s.', 'The Nationalisers', 'Prime Minister Davud Amini', 'We would rather be poor and free than rich and ruled.', 'the Prime Minister, to the parliament', 'The national front survives its enemies: the oil is the nation’s, the parliament governs, and the Shah reigns over nothing much. The Old Lands has a democracy, and the oil companies have a precedent they hate.', { p: 'stripes', a: GREEN, b: PAPER, e: 'diamond', ef: RED }, 'parliament') },
      'Parliament governs, the oil belongs to the nation, and the Shah reigns over nothing.', [['legitmod', 10, 120, 'The Nation’s Oil'], ['nq', 20], ['particip', 12], ['opAll', 4]]],
    ['d_revolution', 'The Revolution of the Faithful', 5, 4, { req: ['seminary'], ideos: ['revival', 'theocracy'], dest: D('Guided Republic of Zandar', 'Neither east nor west.', 'The Revolution', 'The Guide', 'Neither east nor west: the guided republic.', 'the Guide, on his return from exile', 'The preachers have taken the plateau. The Shah is gone, the oil and the bases with him, and the guardians govern in the name of the faith and of the poor. The two blocs will spend a decade trying to decide which of them lost Zandar.', { p: 'hband', a: GREEN, b: RED, e: 'crescent', ef: PAPER }, 'faith') },
      'The religious revolution: no Shah, no bases, no companies.', [['legitmod', 10, 120, 'The Revolution'], ['fervor', 20], ['oil', 'nationalise'], ['opAll', -8]]],
  ], [
    ['p_court', 'The court’s oil', 0, 0, { hist: 1 }, 'Royalties paid to the court and spent by it.', [['nq', -8], ['gold', 80]]],
    ['p_parliament', 'The parliament’s oil committee', 0, 1, { excl: ['p_shah'] }, 'Every oil contract must pass a committee of the parliament.', [['nq', 12], ['particip', 6], ['op', 'Norvik', -8]]],
    ['p_shah', 'The Shah’s prerogative', 0, 2, { excl: ['p_parliament'], hist: 1 }, 'Oil policy reserved to the throne.', [['nq', -12], ['auth', 10]]],
    ['f_aurelia', 'The northern sphere', 0, 3, { year: 1912 }, 'A treaty with Aurelia, whose sphere of influence covers our north.', [n2('Aurelia', 'treaty')], 1],
    ['f_cassine', 'The distant friend', 0, 4, { year: 1945, excl: ['f_aurelia'] }, 'Cassine is far away and has no sphere here: ask it for advisers.', [n2('Cassine', 'aid'), ['op', 'Cassine', 10]], 1],
  ]);

  /* ---------------------------------------------------------------- destiny art, and the Nation screen */
  for (const b of ['Varanth', 'Khemra', 'Baskhar', 'Amaran', 'Tyrrha', 'Sahrem', 'Zandar']) for (const f of ID.FOCUS.nations[b]) if (f.dest && !f.dest.art) f.dest.art = 'parliament';
})();
